-- Performance Pro: execute em projeto Supabase novo. Isolamento de dados via RLS.
create extension if not exists pgcrypto;
do $$ begin create type public.app_role as enum ('coach','athlete'); exception when duplicate_object then null; end $$;
create table if not exists public.teams(id uuid primary key default gen_random_uuid(), name text not null, owner_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, role public.app_role not null default 'athlete', team_id uuid references public.teams(id) on delete set null, created_at timestamptz not null default now());
create table if not exists public.athletes(id uuid primary key default gen_random_uuid(), user_id uuid unique references auth.users(id) on delete set null, team_id uuid not null references public.teams(id) on delete cascade, full_name text not null, email text, birth_date date, sport text, category text, position text, dominant_foot text, height_cm numeric(5,2), body_mass_kg numeric(5,2), notes text, created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.exercises(id uuid primary key default gen_random_uuid(), team_id uuid references public.teams(id) on delete cascade, name text not null, category text not null, target text, video_path text, is_public boolean not null default false, created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now());
create table if not exists public.workouts(id uuid primary key default gen_random_uuid(), team_id uuid not null references public.teams(id) on delete cascade, athlete_id uuid not null references public.athletes(id) on delete cascade, title text not null, scheduled_for date, notes text, created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now());
create table if not exists public.workout_items(id uuid primary key default gen_random_uuid(), workout_id uuid not null references public.workouts(id) on delete cascade, exercise_id uuid references public.exercises(id) on delete set null, exercise_name text not null, sets integer, reps text, load_text text, rest_seconds integer, notes text, sort_order integer not null default 0);
create table if not exists public.monitoring_sessions(id uuid primary key default gen_random_uuid(), athlete_id uuid not null references public.athletes(id) on delete cascade, session_date date not null default current_date, psr numeric(4,1), pse numeric(4,1), duration_min integer, load_ua numeric generated always as (pse * duration_min) stored, jump_pre_cm numeric(6,2), jump_post_cm numeric(6,2), jump_video_pre_path text, jump_video_post_path text, notes text, created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), constraint psr_range check(psr is null or psr between 0 and 20), constraint pse_range check(pse is null or pse between 0 and 10), constraint duration_range check(duration_min is null or duration_min between 0 and 1440));
create or replace function public.current_role() returns public.app_role language sql stable security definer set search_path=public,pg_temp as $$ select role from public.profiles where id=auth.uid() $$;
create or replace function public.current_team_id() returns uuid language sql stable security definer set search_path=public,pg_temp as $$ select team_id from public.profiles where id=auth.uid() $$;
create or replace function public.is_coach() returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select coalesce(public.current_role()='coach',false) $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin insert into public.profiles(id,full_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',split_part(new.email,'@',1)),'athlete') on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.teams enable row level security; alter table public.profiles enable row level security; alter table public.athletes enable row level security; alter table public.exercises enable row level security; alter table public.workouts enable row level security; alter table public.workout_items enable row level security; alter table public.monitoring_sessions enable row level security;
do $$ declare p record; begin for p in select tablename,policyname from pg_policies where schemaname='public' and tablename in ('teams','profiles','athletes','exercises','workouts','workout_items','monitoring_sessions') loop execute format('drop policy if exists %I on public.%I',p.policyname,p.tablename); end loop; end $$;
create policy "profile read self" on public.profiles for select to authenticated using(id=auth.uid());
create policy "profile update self" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
revoke update on public.profiles from authenticated; grant update(full_name) on public.profiles to authenticated;
create policy "team read own" on public.teams for select to authenticated using(id=public.current_team_id() and owner_id=auth.uid());
create policy "athlete read own record or coach team" on public.athletes for select to authenticated using(user_id=auth.uid() or (public.is_coach() and team_id=public.current_team_id() and exists(select 1 from public.teams t where t.id=team_id and t.owner_id=auth.uid())));
create policy "coach insert own team athletes" on public.athletes for insert to authenticated with check(public.is_coach() and team_id=public.current_team_id() and exists(select 1 from public.teams t where t.id=team_id and t.owner_id=auth.uid()));
create policy "coach update own team athletes" on public.athletes for update to authenticated using(public.is_coach() and team_id=public.current_team_id() and exists(select 1 from public.teams t where t.id=team_id and t.owner_id=auth.uid())) with check(public.is_coach() and team_id=public.current_team_id());
create policy "coach delete own team athletes" on public.athletes for delete to authenticated using(public.is_coach() and team_id=public.current_team_id() and exists(select 1 from public.teams t where t.id=team_id and t.owner_id=auth.uid()));
create policy "exercise read public or team" on public.exercises for select to authenticated using(is_public or (public.is_coach() and team_id=public.current_team_id()));
create policy "coach manages exercises" on public.exercises for all to authenticated using(public.is_coach() and team_id=public.current_team_id()) with check(public.is_coach() and team_id=public.current_team_id());
create policy "workout read assigned or coach" on public.workouts for select to authenticated using(athlete_id in(select id from public.athletes where user_id=auth.uid()) or (public.is_coach() and team_id=public.current_team_id() and exists(select 1 from public.teams t where t.id=team_id and t.owner_id=auth.uid())));
create policy "coach manages workouts" on public.workouts for all to authenticated using(public.is_coach() and team_id=public.current_team_id() and exists(select 1 from public.teams t where t.id=team_id and t.owner_id=auth.uid())) with check(public.is_coach() and team_id=public.current_team_id() and exists(select 1 from public.teams t where t.id=team_id and t.owner_id=auth.uid()));
create policy "items read if parent workout readable" on public.workout_items for select to authenticated using(exists(select 1 from public.workouts w where w.id=workout_id));
create policy "coach manages items" on public.workout_items for all to authenticated using(public.is_coach() and exists(select 1 from public.workouts w join public.teams t on t.id=w.team_id where w.id=workout_id and w.team_id=public.current_team_id() and t.owner_id=auth.uid())) with check(public.is_coach() and exists(select 1 from public.workouts w join public.teams t on t.id=w.team_id where w.id=workout_id and w.team_id=public.current_team_id() and t.owner_id=auth.uid()));
create policy "monitoring read own or coach team" on public.monitoring_sessions for select to authenticated using(athlete_id in(select id from public.athletes where user_id=auth.uid()) or (public.is_coach() and athlete_id in(select a.id from public.athletes a join public.teams t on t.id=a.team_id where a.team_id=public.current_team_id() and t.owner_id=auth.uid())));
create policy "coach manages monitoring" on public.monitoring_sessions for all to authenticated using(public.is_coach() and athlete_id in(select a.id from public.athletes a join public.teams t on t.id=a.team_id where a.team_id=public.current_team_id() and t.owner_id=auth.uid())) with check(public.is_coach() and athlete_id in(select a.id from public.athletes a join public.teams t on t.id=a.team_id where a.team_id=public.current_team_id() and t.owner_id=auth.uid()));
-- Convites devem ocorrer somente via Edge Function usando SERVICE_ROLE no servidor. Nunca exponha essa chave no app.
